import Foundation
import SwiftUI
fileprivate func listOf<T>(_ elements: T...) -> [T] { elements }
fileprivate typealias Pair = DiagnosticCommand

// MARK: - Tech-Knowledge Base Models

public enum KnowledgeDifficulty: String, Codable, CaseIterable {
    case beginner = "Beginner"
    case intermediate = "Intermediate"
    case advanced = "Advanced"

    public var displayName: String { rawValue }
}

public enum KnowledgeDomain: String, Codable, CaseIterable {
    case hardware = "Hardware"
    case software = "Software"
    case hybrid = "Hardware & Software"

    public var displayName: String { rawValue }
}

public struct DiagnosticCommand: Codable, Equatable, Hashable {
    public let command: String
    public let description: String
    public init(_ command: String, _ description: String = "") {
        self.command = command
        self.description = description
    }
}

public struct TroubleshootingArticle: Identifiable, Codable, Equatable {
    public let id: String
    public let category: String
    public let hubCategory: String
    public let subcategory: String
    public let problemTitle: String
    public let tamilTitle: String?
    public let operatingSystemOrModel: String
    public let symptoms: [String]
    public let possibleCauses: [String]
    public let difficultyLevel: KnowledgeDifficulty
    public let domain: KnowledgeDomain
    public let requiredTools: [String]
    public let stepByStepSolution: [String]
    public let diagnosticCommands: [DiagnosticCommand]?
    public let expectedResult: String?
    public let safetyPrecautions: String?
    public let whenToEscalate: String?
    public let officialReferenceUrl: String?
    public let lastVerifiedDate: String
    public let tamilExplanation: String?

    public var title: String { problemTitle }
    public var difficulty: KnowledgeDifficulty { difficultyLevel }
    public var toolsRequired: [String] { requiredTools }
    public var solutionSteps: [String] { stepByStepSolution }
    public var escalationGuidelines: String? { whenToEscalate }
    public var estimatedReadTime: String {
        let count = symptoms.count + possibleCauses.count + stepByStepSolution.count
        return count <= 8 ? "3 min read" : (count <= 14 ? "5 min read" : "8 min read")
    }

    public init(
        id: String,
        category: String,
        hubCategory: String,
        subcategory: String,
        problemTitle: String,
        tamilTitle: String? = nil,
        operatingSystemOrModel: String,
        symptoms: [String],
        possibleCauses: [String],
        difficultyLevel: KnowledgeDifficulty,
        domain: KnowledgeDomain,
        requiredTools: [String],
        stepByStepSolution: [String],
        diagnosticCommands: [DiagnosticCommand]? = nil,
        expectedResult: String? = nil,
        safetyPrecautions: String? = nil,
        whenToEscalate: String? = nil,
        officialReferenceUrl: String? = nil,
        lastVerifiedDate: String = "23/11/2026",
        tamilExplanation: String? = nil
    ) {
        self.id = id
        self.category = category
        self.hubCategory = hubCategory
        self.subcategory = subcategory
        self.problemTitle = problemTitle
        self.tamilTitle = tamilTitle
        self.operatingSystemOrModel = operatingSystemOrModel
        self.symptoms = symptoms
        self.possibleCauses = possibleCauses
        self.difficultyLevel = difficultyLevel
        self.domain = domain
        self.requiredTools = requiredTools
        self.stepByStepSolution = stepByStepSolution
        self.diagnosticCommands = diagnosticCommands
        self.expectedResult = expectedResult
        self.safetyPrecautions = safetyPrecautions
        self.whenToEscalate = whenToEscalate
        self.officialReferenceUrl = officialReferenceUrl
        self.lastVerifiedDate = lastVerifiedDate
        self.tamilExplanation = tamilExplanation
    }
}

public struct DailyTechTip: Identifiable, Codable, Equatable {
    public let id: String
    public let dayOfYear: Int
    public let title: String
    public let category: String
    public let tipText: String
    public let commandOrShortcut: String?
    public let tamilExplanation: String?

    public init(id: String, dayOfYear: Int, title: String, category: String, tipText: String, commandOrShortcut: String? = nil, tamilExplanation: String? = nil) {
        self.id = id
        self.dayOfYear = dayOfYear
        self.title = title
        self.category = category
        self.tipText = tipText
        self.commandOrShortcut = commandOrShortcut
        self.tamilExplanation = tamilExplanation
    }
}

public struct AiPrompt: Identifiable, Codable, Equatable {
    public let id: String
    public let title: String
    public let targetTool: String
    public let category: String
    public let promptText: String
    public let explanation: String

    public var prompt: String { promptText }

    public init(id: String, title: String, targetTool: String, category: String, promptText: String, explanation: String) {
        self.id = id
        self.title = title
        self.targetTool = targetTool
        self.category = category
        self.promptText = promptText
        self.explanation = explanation
    }
}

