            possibleCauses: listOf("MTU (Maximum Transmission Unit) packet size mismatch over PPPoE broadband connection", "Packets larger than 1492 bytes fragmented and dropped by ISP router without ICMP notification ('PMTU Black Hole')"),
            difficultyLevel: .intermediate,
            domain: .software,
            requiredTools: listOf("Command Prompt as Administrator"),
            stepByStepSolution: listOf("Detect optimal MTU size: Open CMD and run: 'ping google.com -f -l 1472'.", "If it returns 'Packet needs to be fragmented but DF set', reduce number by 10 (e.g. 1462, 1452, 1442) until ping replies successfully.", "Take the highest pingable payload size and add 28 (IP/ICMP header): e.g. 1444 + 28 = 1472 Optimal MTU.", "Apply MTU to network interface in Admin CMD:", "View interface names: 'netsh interface ipv4 show subinterfaces'.", "Set new MTU (e.g. for 'Ethernet'): 'netsh interface ipv4 set subinterface \"Ethernet\" mtu=1472 store=persistent'.", "Re-open web browser. All HTTPS portals will now load instantaneously without hanging."),
            diagnosticCommands: listOf(DiagnosticCommand("ping 8.8.8.8 -f -l 1472", "Tests Don't-Fragment (DF) packet transmission at specific byte size"), DiagnosticCommand("netsh interface ipv4 show subinterfaces", "Displays active MTU sizes for all network adapters")),
