    public static func getTodayTip() -> DailyTechTip {
        let dayOfYear = Calendar.current.ordinality(of: .day, in: .year, for: Date()) ?? 1
        let index = (dayOfYear - 1) % dailyTips.count
        return dailyTips[index]
    }

    public static func searchArticles(
        query: String,
        selectedCategory: String? = nil,
        selectedDifficulty: KnowledgeDifficulty? = nil,
        selectedDomain: KnowledgeDomain? = nil
    ) -> [TroubleshootingArticle] {
        let cleanQuery = query.trimmingCharacters(in: .whitespacesAndNewlines).lowercased()
        return articles.filter { article in
            let matchesCategory = selectedCategory == nil || article.category == selectedCategory || article.hubCategory == selectedCategory
            let matchesDifficulty = selectedDifficulty == nil || article.difficultyLevel == selectedDifficulty
            let matchesDomain = selectedDomain == nil || article.domain == selectedDomain

            let matchesQuery = cleanQuery.isEmpty ||
                article.id.lowercased().contains(cleanQuery) ||
                article.problemTitle.lowercased().contains(cleanQuery) ||
                (article.tamilTitle?.lowercased().contains(cleanQuery) == true) ||
                article.operatingSystemOrModel.lowercased().contains(cleanQuery) ||
                article.symptoms.contains { $0.lowercased().contains(cleanQuery) } ||
                article.possibleCauses.contains { $0.lowercased().contains(cleanQuery) } ||
                article.stepByStepSolution.contains { $0.lowercased().contains(cleanQuery) } ||
                (article.diagnosticCommands?.contains { $0.command.lowercased().contains(cleanQuery) || $0.description.lowercased().contains(cleanQuery) } == true)

            return matchesCategory && matchesDifficulty && matchesDomain && matchesQuery
        }
    }
}
